// [name, position, age, rating*10, goals, assists, club]
type PD = [string, string, number, number, number, number, string];

function makePlayers(teamId: string, country: string, defs: PD[]): Player[] {
  return defs.map(([name, pos, age, rat, goals, assists, club], i) => {
    const rating = rat / 10;
    const isGK = pos === 'GK';
    const isDef = ['CB','RB','LB'].includes(pos);
    const isMid = ['DM','CM','AM'].includes(pos);
    const mv = Math.max(2, Math.round((rat - 60) * 2.8 + goals * 3.5 + assists * 2));
    const fp = Math.max(5, goals * 8 + assists * 5 + Math.round((rat - 68) * 2.2) + (isGK ? 20 : 0));
    const ir: 'low'|'medium'|'high' = age >= 35 ? 'high' : age >= 32 ? 'medium' : 'low';
    const mp = Math.max(45, i === 0 ? 450 : i < 11 ? Math.max(180, 400 - i * 25) : 180 - (i - 11) * 8);
    return {
      id: `${teamId}_${i}`, name, country, position: pos, club, age, goals, assists, rating,
      marketValueM: mv, fantasyPoints: fp, injuryRisk: ir, minutesPlayed: mp,
      yellowCards: Math.floor(mp / 180), redCards: 0,
      keyPasses: isGK ? 2 : isDef ? assists * 2 + 4 : isMid ? goals * 2 + assists * 3 + 8 : goals + assists * 2 + 5,
      tacklesWon: isGK ? 0 : isDef ? 16 : isMid ? 10 : 4,
      cleanSheets: isGK ? Math.max(0, Math.floor((rat - 70) / 4)) : isDef && i < 5 ? Math.max(0, Math.floor((rat - 72) / 5)) : 0,
    };
  });
}

